                        changed = 0
                    elif put_mode == 'replace':
                        work[key] = val
                        changed = 1
                        trig_fired = 1
                    else:
                        work[key] = val
                        changed = 1
                        trig_fired = 0
                else:
                    work[key] = val
                    changed = 1
                    trig_fired = 1
            else:
                if key in work:
                    work[key] = val
                    changed = 1
                else:
                    changed = 0
            direct = changed
            trig_changes = trig_fired if trig == 'after_insert' else 0
            tc[conn] += direct + trig_changes
            last_ch[conn] = direct + trig_changes

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'begin':
                if tx[conn] is None:
                    tx[conn] = dict(db)
            elif op == 'commit':
                if tx[conn] is not None:
                    db.clear()
                    db.update(tx[conn])
                    tx[conn] = None
            elif op == 'rollback':
                tx[conn] = None
