                do_write(conn, act['key'], act['value'], 'put')
            elif op == 'update':
                do_write(conn, act['key'], act['value'], 'update')
            elif op == 'delete':
                work = tx[conn] if tx[conn] is not None else db
                if act['key'] in work:
                    del work[act['key']]
                    changed = 1
                else:
