        elif chan == 'total_main':
            ch = tc['main']
        else:
            ch = tc['main'] + tc['other']
        cnt = len(db)
        sm = sum(db.values())
        return (ch, cnt, sm)

    # Filter family members
    put_modes = ['ignore', 'replace', 'upsert']
    trigs = ['none', 'after_insert']
    chans = ['changes', 'total_main', 'total_other']

    candidates = []
    for pm in put_modes:
        for tg in trigs:
            for ch in chans:
                ok = True
                for rec in hist:
                    acts = rec['actions']
                    obs = rec['observed']
                    try:
                        c, cnt, sm = simulate2(pm, tg, ch, acts)
                    except Exception:
                        ok = False
                        break
                    if c != obs['channel'] or cnt != obs['committed_count'] or sm != obs['committed_sum']:
                        ok = False
                        break
                if ok:
                    candidates.append((pm, tg, ch))

    goal = context['goal']
    actions = context['actions']

    if not candidates:
        return {'value': None, 'unresolved': True}

    vals = set()
    for pm, tg, ch in candidates:
        c, cnt, sm = simulate2(pm, tg, ch, actions)
        if goal == 'channel':
            vals.add(c)
        elif goal == 'committed_count':
            vals.add(cnt)
        else:
            vals.add(sm)

    if len(vals) == 1:
        return {'value': vals.pop(), 'unresolved': False}
    return {'value': None, 'unresolved': True}

