    def simulate(actions, put_op, channel_type, trigger):
        committed = {}
        main_tx = None
        other_tx = None
        total_main = 0
        total_other = 0
        last_changes_main = 0

        def effective(conn):
            tx = main_tx if conn == 'main' else other_tx
            eff = dict(committed)
            if tx is not None:
                for k, v in tx.items():
                    if v is None:
                        if k in eff:
                            del eff[k]
                    else:
                        eff[k] = v
            return eff

        def write(conn, key, value):
            if conn == 'main':
                if main_tx is not None:
                    main_tx[key] = value
                else:
                    committed[key] = value
            else:
                if other_tx is not None:
                    other_tx[key] = value
                else:
                    committed[key] = value

        def remove(conn, key):
            if conn == 'main':
                if main_tx is not None:
                    main_tx[key] = None
                else:
                    if key in committed:
                        del committed[key]
            else:
                if other_tx is not None:
                    other_tx[key] = None
                else:
                    if key in committed:
                        del committed[key]

        for action in actions:
            op = action.get('op')
            conn = action.get('connection', 'main')
            if op == 'put':
                key = action['key']
                value = action['value']
                eff = effective(conn)
                exists = key in eff
                changes = 0
                if put_op == 'ignore':
                    if not exists:
                        changes = 1
                        write(conn, key, value)
                else:
                    changes = 1
                    write(conn, key, value)
                if conn == 'main':
                    total_main += changes
                    last_changes_main = changes
                else:
                    total_other += changes
                if trigger and changes > 0:
                    if conn == 'main':
                        total_main += 1
                    else:
                        total_other += 1
            elif op == 'update':
                key = action['key']
                value = action['value']
                eff = effective(conn)
                if key in eff:
                    changes = 1
                    write(conn, key, value)
                else:
                    changes = 0
                if conn == 'main':
                    total_main += changes
                    last_changes_main = changes
                else:
                    total_other += changes
            elif op == 'delete':
                key = action['key']
                eff = effective(conn)
                if key in eff:
                    changes = 1
                    remove(conn, key)
                else:
                    changes = 0
                if conn == 'main':
                    total_main += changes
                    last_changes_main = changes
                else:
                    total_other += changes
            elif op == 'begin':
                if conn == 'main':
                    main_tx = {}
                else:
                    other_tx = {}
            elif op == 'commit':
                if conn == 'main':
                    if main_tx is not None:
                        for k, v in main_tx.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        main_tx = None
                else:
                    if other_tx is not None:
                        for k, v in other_tx.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        other_tx = None
            elif op == 'rollback':
                if conn == 'main':
                    main_tx = None
                else:
                    other_tx = None

        if channel_type == 'changes':
            channel = last_changes_main
        elif channel_type == 'total_main':
            channel = total_main
        else:
            channel = total_main + total_other

        return channel, len(committed), sum(committed.values())

    put_ops = ['ignore', 'replace', 'upsert']
    channel_types = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    consistent = []
    for put_op in put_ops:
        for channel_type in channel_types:
            for trigger in triggers:
                ok = True
                for receipt in history:
                    ch, cc, cs = simulate(receipt['actions'], put_op, channel_type, trigger)
                    obs = receipt['observed']
                    if ch != obs['channel'] or cc != obs['committed_count'] or cs != obs['committed_sum']:
                        ok = False
                        break
                if ok:
                    consistent.append((put_op, channel_type, trigger))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context['goal']
